function loadScannerLibrary(){
 if(typeof Html5Qrcode!=='undefined')return Promise.resolve();
 if(scannerLibraryPromise)return scannerLibraryPromise;
 scannerLibraryPromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='assets/html5-qrcode.min.js?v=2.3.8';script.onload=resolve;script.onerror=()=>reject(new Error('Library pemindai tidak berhasil dimuat.'));document.head.appendChild(script)});
 return scannerLibraryPromise;
}

