  financeChartInterval(){const max=Math.max(1,...(this.shopeeFinance?.days||[]).map(day=>Number(day.payout)||0));const rough=max/5;const magnitude=10**Math.floor(Math.log10(rough));const normalized=rough/magnitude;return(normalized<=1?1:normalized<=2?2:normalized<=2.5?2.5:normalized<=5?5:10)*magnitude},
