  async loadOrders(){const previousRows=new Map((this.pageData.items||[]).map(row=>[row.order_sn,row])),previous=new Map();for(const row of this.pageData.items||[])for(const line of row.items||[])previous.set(String(line.id),line);const data=await this.api('orders',{query:{q:this.query,filter:this.filter,paper:this.paperFilter,page:this.page}});for(const row of data.items){const oldRow=previousRows.get(row.order_sn);row.label_printer=oldRow?.label_printer||(data.printers.includes(data.defaultLabelPrinter)?data.defaultLabelPrinter:(data.printers[0]||''));row.label_fetching=Boolean(oldRow?.label_fetching);row.label_printing=Boolean(oldRow?.label_printing);for(const line of row.items){const old=previous.get(String(line.id));line.selected_printer=old?.selected_printer||(line.printer_available?line.default_printer:(data.printers[0]||''));if(old?.print_options)line.print_options=old.print_options;if(old?.queued&&!line.queued&&line.print_options){if(line.printed_odd&&!line.printed_even&&line.print_options.parity==='odd')line.print_options.parity='even';else if(line.printed_even&&!line.printed_odd&&line.print_options.parity==='even')line.print_options.parity='odd'}line.queued=Boolean(line.queued);line.queueing=false}}this.pageData=data},
