  async loadQueueWidget(){if(this.queueWidgetLoading){this.queueWidgetRefreshPending=true;return}this.queueWidgetLoading=true;this.queueWidgetRefreshPending=false;try{this.queueData=await this.api('commands')}catch(e){if(e.status===401)throw e}finally{this.queueWidgetLoading=false;if(this.queueWidgetRefreshPending){this.queueWidgetRefreshPending=false;setTimeout(()=>this.loadQueueWidget(),250)}}},
  async loadMapping(){this.mappingData=await this.api('mapping',{query:{q:this.query,page:this.page}})},
