  async loadRandomPool(){this.randomPool=await this.api('random_pool')},
  async loadPrinterSettings(){this.printerSettings=await this.api('printer_settings')},
  async loadOAuth(){const data=await this.api('oauth_status');this.oauthData=data;for(const provider of ['shopee','tiktok'])Object.assign(this.oauthForms[provider],data.items[provider].config);this.oauthForms.shopee.partner_key='';this.oauthForms.tiktok.app_secret=''},
