  async copyText(value){try{await navigator.clipboard.writeText(value);this.notify('Callback URL disalin.')}catch{this.notify('Tidak bisa menyalin otomatis.','error')}},oauthStatusLabel(item){return item.connected?'Terhubung':item.status==='error'?'Perlu tindakan':item.configured?'Siap dihubungkan':'Belum dikonfigurasi'},oauthStatusClass(item){return item.connected?'green':item.status==='error'?'red':item.configured?'amber':'gray'},
  togglePrinter(printer,checked){const visible=new Set(this.printerSettings.visible);checked?visible.add(printer):visible.delete(printer);this.printerSettings.visible=[...visible];if(!this.printerSettings.visible.includes(this.printerSettings.default_label_printer))this.printerSettings.default_label_printer=this.printerSettings.visible[0]||'';if(!this.printerSettings.visible.includes(this.printerSettings.override_brother))this.printerSettings.override_brother='';if(!this.printerSettings.visible.includes(this.printerSettings.override_l3210))this.printerSettings.override_l3210=''},
