  async setOrderItemPrinted(line,printed){line.marking_printed=true;try{const result=await this.api('set_order_item_printed',{body:{line_id:line.id,printed}});if(!printed)this.notify(`Item order ${result.order_sn} dikembalikan ke Belum tercetak.`);else this.notify(result.remaining?`Item ditandai sudah dicetak. Masih ada ${result.remaining} item belum dicetak.`:`Semua item order ${result.order_sn} sudah dicetak.`);await this.loadOrders()}catch(e){this.notify(e.message,'error')}finally{line.marking_printed=false}},
