  async loadInventorySuggestions(){clearTimeout(this.searchTimer);this.inventoryAdd.selected=null;this.searchTimer=setTimeout(async()=>{if(!this.inventoryAdd.query.trim()){this.inventorySuggestions=[];return}try{const data=await this.api('inventory_suggestions',{query:{q:this.inventoryAdd.query}});this.inventorySuggestions=data.items}catch(e){this.notify(e.message,'error')}},250)},
