  async openInventoryScanner(){this.scannerOpen=true;this.scannerMatches=[];this.scannerError=false;this.scannerStatus='Menyiapkan kamera…';await this.$nextTick();try{await loadScannerLibrary()}catch(e){this.scannerError=true;this.scannerStatus='Pemindai tidak berhasil dimuat. Gunakan input nomor order manual.';return}try{inventoryScanner=new Html5Qrcode('inventory-barcode-reader',{formatsToSupport:[Html5QrcodeSupportedFormats.QR_CODE,Html5QrcodeSupportedFormats.CODE_128,Html5QrcodeSupportedFormats.CODE_39,Html5QrcodeSupportedFormats.CODE_93,Html5QrcodeSupportedFormats.ITF,Html5QrcodeSupportedFormats.EAN_13,Html5QrcodeSupportedFormats.EAN_8]});await inventoryScanner.start({facingMode:'environment'},{fps:10,qrbox:(w,h)=>({width:Math.min(w-32,320),height:Math.min(Math.max(100,Math.round(h*.35)),180)}),aspectRatio:1.777778},text=>this.handleInventoryScan(text),()=>{});this.scannerStatus='Arahkan barcode ke dalam kotak.'}catch(e){this.scannerError=true;this.scannerStatus=location.protocol==='https:'||location.hostname==='localhost'?'Kamera tidak dapat dibuka. Izinkan akses kamera atau gunakan tombol foto.':'Akses kamera langsung membutuhkan HTTPS. Gunakan tombol foto di bawah ini.'}},
  async stopInventoryScanner(){if(!inventoryScanner)return;try{if(inventoryScanner.isScanning)await inventoryScanner.stop()}catch{}try{inventoryScanner.clear()}catch{}inventoryScanner=null},
  async closeInventoryScanner(){await this.stopInventoryScanner();this.scannerOpen=false;this.scannerMatches=[]},
  async handleInventoryScan(text){if(!text||this.scannerStatus==='Mencari order…')return;this.scannerStatus='Mencari order…';this.scannerError=false;await this.stopInventoryScanner();await this.lookupInventoryOrder(text,true)},
  async scanInventoryPhoto(event){const file=event.target.files?.[0];event.target.value='';if(!file)return;this.scannerMatches=[];this.scannerError=false;this.scannerStatus='Membaca foto…';try{await this.stopInventoryScanner();await this.$nextTick();inventoryScanner=new Html5Qrcode('inventory-barcode-reader');const result=await inventoryScanner.scanFile(file,true);await this.handleInventoryScan(result)}catch(e){this.scannerError=true;this.scannerStatus='Barcode belum terbaca. Coba foto lebih dekat, terang, dan tidak miring.'}},
  async lookupInventoryOrder(code,fromScanner=false){code=String(code||'').trim();if(!code)return;try{const data=await this.api('inventory_order_lookup',{query:{code}});if(!data.items.length){if(fromScanner){this.scannerError=true;this.scannerStatus=`Nomor resi terbaca (${code}), tetapi order tidak ditemukan.`}else this.notify(`Order tidak ditemukan dari nomor resi/kode ${code}.`,'error');return}this.scannerMatches=data.items;if(data.items.length===1)this.selectScannedOrder(data.items[0],code);else if(fromScanner)this.scannerStatus=`Nomor resi terbaca. Ditemukan ${data.items.length} kemungkinan order.`}catch(e){const message=`${e.message||'Gagal mencari order.'} — nomor resi hasil barcode: ${code}`;if(fromScanner){this.scannerError=true;this.scannerStatus=message}else this.notify(message,'error')}},
  async selectScannedOrder(order,scannedCode=''){this.inventoryOrderSn=order.order_sn;this.inventoryOrderPreview=order;const resi=scannedCode||order.tracking_number;this.notify(`${resi?`Resi ${resi} → `:''}Order ${order.order_sn} ditemukan. Periksa daftar item sebelum menambahkan.`);await this.closeInventoryScanner()},
  async addInventoryOrder(){if(!this.inventoryOrderPreview||this.inventoryOrderAdding)return;this.inventoryOrderAdding=true;try{const result=await this.api('inventory_add_order',{body:{order_sn:this.inventoryOrderPreview.order_sn}});this.notify(`${result.lines} item order ditambahkan ke inventory.`);this.inventoryOrderSn='';this.inventoryOrderPreview=null;await this.loadInventory()}catch(e){this.notify(e.message,'error')}finally{this.inventoryOrderAdding=false}},
