  async jobAction(row,operation){if(row.deleting||this.queueActionKey)return;if(operation==='delete')row.deleting=true;this.queueActionKey=`app-${row.id}`;try{await this.api('print_job_action',{body:{id:row.id,operation}});this.notify(`Job #${row.id} diperbarui.`);await this.loadQueueWidget()}catch(e){row.deleting=false;this.notify(e.message,'error')}finally{this.queueActionKey=''}},
