  async uploadManualPdf(event){const file=event.target.files?.[0];event.target.value='';if(!file)return;const form=new FormData();form.append('pdf',file);this.busy=true;try{const response=await fetch('api.php?action=upload_manual_pdf',{method:'POST',body:form});const data=await response.json();if(!response.ok)throw new Error(data.error||`HTTP ${response.status}`);this.notify(`${data.name} tersimpan (${data.pages} halaman).`);await this.loadManualPdfs()}catch(e){this.notify(e.message,'error')}finally{this.busy=false}},
  async loadMappingPdfChoices(){const picker=this.mappingPdfPicker;picker.loading=true;try{const data=await this.api('manual_mapping_pdfs',{query:{q:picker.query}});picker.items=data.items}catch(e){this.notify(e.message,'error')}finally{picker.loading=false}},
  searchMappingPdfs(){const picker=this.mappingPdfPicker;picker.selected=null;clearTimeout(this.mappingPdfTimer);this.mappingPdfTimer=setTimeout(()=>this.loadMappingPdfChoices(),250)},
