  async printMappingPdf(){const picker=this.mappingPdfPicker;if(!picker.selected){this.notify('Pilih PDF dari Data Mapping terlebih dahulu.','error');return}if(!picker.printer){this.notify('Pilih printer terlebih dahulu.','error');return}picker.printing=true;try{const result=await this.api('print_mapping_pdf',{body:{mapping_id:picker.selected.id,printer:picker.printer,settings:picker.settings}});this.notify(`PDF mapping masuk antrean sebagai job #${result.id}.`);this.loadQueueWidget()}catch(e){this.notify(e.message,'error')}finally{picker.printing=false}},
  async openPdfDrawer(url,title,kind='document'){this.ensurePdfDrawerHistory();this.labelPreview={url,title:title||'Dokumen PDF',kind};this.labelPdfState={loading:true,error:'',page:0,pages:0,zoom:100};await this.$nextTick();try{const{PaperbellPdfViewer}=await import('./pdf-viewer.mjs?v=5');if(labelPdfViewer&&labelPdfViewer.canvas!==this.$refs.labelPdfCanvas){await labelPdfViewer.destroy();labelPdfViewer=null}if(!labelPdfViewer)labelPdfViewer=new PaperbellPdfViewer({container:this.$refs.labelPdfViewport,canvas:this.$refs.labelPdfCanvas,onState:state=>{this.labelPdfState=state}});await labelPdfViewer.load(url)}catch(error){console.error('PDF.js gagal dimuat',error);this.labelPdfState={...this.labelPdfState,loading:false,error:'Preview PDF tidak dapat dimuat. Coba buka di tab baru.'}}},
