  async generateRandom(){this.busy=true;try{const result=await this.api('generate_random',{body:this.randomForm});this.notify(`Random Pages selesai: ${result.pages} halaman.`);this.go('manual')}catch(e){this.notify(e.message,'error')}finally{this.busy=false}},
  async openLabel(sn){const url=`api.php?action=label_pdf&order_sn=${encodeURIComponent(sn)}`;this.ensurePdfDrawerHistory();this.labelPreview={order_sn:sn,url};this.labelPdfState={loading:true,error:'',page:0,pages:0,zoom:100};await this.$nextTick();try{const{PaperbellPdfViewer}=await import('./pdf-viewer.mjs?v=5');if(labelPdfViewer&&labelPdfViewer.canvas!==this.$refs.labelPdfCanvas){await labelPdfViewer.destroy();labelPdfViewer=null}if(!labelPdfViewer)labelPdfViewer=new PaperbellPdfViewer({container:this.$refs.labelPdfViewport,canvas:this.$refs.labelPdfCanvas,onState:state=>{this.labelPdfState=state}});await labelPdfViewer.load(url)}catch(error){console.error('PDF.js gagal dimuat',error);this.labelPdfState={...this.labelPdfState,loading:false,error:'Preview PDF tidak dapat dimuat. Coba buka di tab baru.'}}},
